// derived from Python 3.12.3's unicodedata (Unicode 15.0.0):
// for every codepoint whose str.lower() yields exactly one codepoint, record
// [start, end] stepping by 1 or 2 with a constant (lower - upper) delta. This
// is script-agnostic by construction — it covers every alphabet with a simple
// case pairing (Latin, Greek, Cyrillic, Armenian, Cherokee, Deseret, ...)
// without a single hardcoded script range in the caller.
// Special casings (e.g. Turkish "I" / German capital ẞ -> "ss") are skipped:
// those need multi-codepoint output, which a codepoint->codepoint fold can't
// represent, and dictionary lookup only needs a stable, reversible-ish fold.
#pragma once
#include <cstdint>

struct Utf8CaseFoldRange {
  uint32_t start;
  uint32_t end;
  uint8_t step;
  int32_t delta;
};

